import { Task, TaskStatus } from '../../domain/entities/Task';
import { TaskRepository } from '../../domain/repositories/TaskRepository';

export class ListTasksUseCase {
  constructor(private taskRepository: TaskRepository) {}

  executeByStatus(projectId: string, status: TaskStatus): Task[] {
    return this.taskRepository.findByProjectIdAndStatus(projectId, status);
  }

  executeByAssignee(projectId: string, assigneeId: string): Task[] {
    return this.taskRepository.findByProjectIdAndAssignee(projectId, assigneeId);
  }

  executeAll(projectId: string): Task[] {
    return this.taskRepository.findByProjectId(projectId);
  }
}

